16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Single source of truth for the fixed city-to-region mapping (Sydney->NSW, Melbourne->VIC,
22	 * Brisbane->QLD). Consumed by presentation (an owner's {@code locality}) and by validation (an
23	 * owner's postcode range), so both layers agree on which region a city belongs to.
24	 */
25	public final class Region {
26	
27	    /** Locality reported for a city that has no known region. */
28	    public static final String UNKNOWN = "UNKNOWN";
29	
30	    /** Fixed city-to-region lookup. */
31	    private static final Map<String, String> CITY_REGION = Map.of(
32	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    /** Region -> inclusive 4-digit postcode range {low, high}. */
35	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
36	        "NSW", new int[] {2000, 2099},
37	        "VIC", new int[] {3000, 3099},
38	        "QLD", new int[] {4000, 4099});
39	
40	    /** Fixed region-to-timezone lookup, as IANA names. */
41	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
42	        "NSW", "Australia/Sydney",
43	        "VIC", "Australia/Melbourne",
44	        "QLD", "Australia/Brisbane");
45	
46	    private Region() {
47	    }
48	
49	    /**
50	     * The canonical region for {@code city}, or {@code null} when the city has no known region.
51	     */
52	    public static String forCity(String city) {
53	        return CITY_REGION.get(city);
54	    }
55	
56	    /**
57	     * The canonical region whose range contains the given 4-digit {@code postcode}, or {@code null}
58	     * when the postcode is absent, not a number, or falls in no known range.
59	     */
60	    public static String forPostcode(String postcode) {
61	        if (postcode == null) {
62	            return null;
63	        }
64	        int value;
65	        try {
66	            value = Integer.parseInt(postcode.trim());
67	        } catch (NumberFormatException e) {
68	            return null;
69	        }
70	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
71	            int[] range = entry.getValue();
72	            if (value >= range[0] && value <= range[1]) {
73	                return entry.getKey();
74	            }
75	        }
76	        return null;
77	    }
78	
79	    /**
80	     * Whether {@code region} is one of the known regions (NSW, VIC or QLD). {@code false} for
81	     * {@link #UNKNOWN}, {@code null}, or any other value.
82	     */
83	    public static boolean isKnownRegion(String region) {
84	        return REGION_POSTCODES.containsKey(region);
85	    }
86	
87	    /**
88	     * The inclusive 4-digit postcode range {@code {low, high}} for {@code region}, or {@code null}
89	     * when the region has no defined range. Returns a fresh array so callers cannot mutate the table.
90	     */
91	    public static int[] postcodeRange(String region) {
92	        int[] range = REGION_POSTCODES.get(region);
93	        return range == null ? null : new int[] {range[0], range[1]};
94	    }
95	
96	    /**
97	     * The canonical region for {@code city}, or {@link #UNKNOWN} when the city has no known region.
98	     */
99	    public static String localityForCity(String city) {
100	        String region = forCity(city);
101	        return region == null ? UNKNOWN : region;
102	    }
103	
104	    /**
105	     * The canonical region derived from the given 4-digit {@code postcode} (see
106	     * {@link #forPostcode(String)}), or {@link #UNKNOWN} when the postcode is absent or falls in no
107	     * known range. This is the {@code <REGION>} component of an owner's {@code memberId}.
108	     */
109	    public static String regionForPostcode(String postcode) {
110	        String region = forPostcode(postcode);
111	        return region == null ? UNKNOWN : region;
112	    }
113	
114	    /**
115	     * The {@code <REGION>} prefix of a {@code memberId} formatted
116	     * {@code '<REGION><FY><HASH8><CHK>'} — one of the known regions (NSW, VIC, QLD) when the
117	     * memberId begins with it, otherwise {@link #UNKNOWN} (which also covers a memberId that is
118	     * {@code null}, blank, or begins with the literal {@code UNKNOWN} region). The matching layout
119	     * is produced by {@code ClinicServiceImpl.generateMemberId}; keep the two in sync.
120	     */
121	    public static String regionOfMemberId(String memberId) {
122	        if (memberId == null || memberId.isBlank()) {
123	            return UNKNOWN;
124	        }
125	        for (String region : REGION_POSTCODES.keySet()) {
126	            if (memberId.startsWith(region)) {
127	                return region;
128	            }
129	        }
130	        return UNKNOWN;
131	    }
132	
133	    /**
134	     * The IANA timezone name for {@code region} via the fixed region-to-timezone table
135	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null}
136	     * when the region has no mapped timezone (e.g. {@link #UNKNOWN} or {@code null}).
137	     */
138	    public static String timezoneForRegion(String region) {
139	        return REGION_TIMEZONE.get(region);
140	    }
141	
142	    /**
143	     * The canonical region derived by preferring the {@code postcode} range, and only falling back
144	     * to the city-to-region table when the postcode is absent or in no known range. Returns
145	     * {@link #UNKNOWN} when neither the postcode nor the city yields a region.
146	     */
147	    public static String locality(String city, String postcode) {
148	        String region = forPostcode(postcode);
149	        if (region == null) {
150	            region = forCity(city);
151	        }
152	        return region == null ? UNKNOWN : region;
153	    }
154	}
