49	/**
50	 * Mostly used as a facade for all Petclinic controllers
51	 * Also a placeholder for @Transactional and @Cacheable annotations
52	 *
53	 * @author Michael Isvy
54	 * @author Vitaliy Fedoriv
55	 */
56	@Service
57	public class ClinicServiceImpl implements ClinicService {
58	
59	    /** Dedicated audit trail logger for owner-lifecycle side-effects. */
60	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
61	
62	    /** Dedicated logger for enqueued owner notifications (e.g. the welcome notification). */
63	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
64	
65	    /** Serializes structured audit events to compact JSON. */
66	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
67	
68	    /** Monotonically increasing sequence number stamped on each structured owner-create event. */
69	    private static final AtomicLong OWNER_CREATED_SEQ = new AtomicLong();
70	
71	    private final PetRepository petRepository;
72	    private final VetRepository vetRepository;
73	    private final OwnerRepository ownerRepository;
74	    private final VisitRepository visitRepository;
75	    private final SpecialtyRepository specialtyRepository;
76	    private final PetTypeRepository petTypeRepository;
77	
78	    public ClinicServiceImpl(
79	        PetRepository petRepository,
80	        VetRepository vetRepository,
81	        OwnerRepository ownerRepository,
82	        VisitRepository visitRepository,
83	        SpecialtyRepository specialtyRepository,
84	        PetTypeRepository petTypeRepository) {
85	        this.petRepository = petRepository;
86	        this.vetRepository = vetRepository;
87	        this.ownerRepository = ownerRepository;
88	        this.visitRepository = visitRepository;
89	        this.specialtyRepository = specialtyRepository;
90	        this.petTypeRepository = petTypeRepository;
91	    }
92	
93	    @Override
94	    @Transactional(readOnly = true)
95	    public Collection<Pet> findAllPets() throws DataAccessException {
96	        return petRepository.findAll();
97	    }
98	
99	    @Override
100	    @Transactional(readOnly = true)
101	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
102	        return petRepository.findAll(pageable);
103	    }
104	
105	    @Override
106	    @Transactional
107	    public void deletePet(Pet pet) throws DataAccessException {
108	        petRepository.delete(pet);
109	    }
110	
111	    @Override
112	    @Transactional(readOnly = true)
113	    public Visit findVisitById(int visitId) throws DataAccessException {
114	        return findEntityById(() -> visitRepository.findById(visitId));
115	    }
116	
117	    @Override
118	    @Transactional(readOnly = true)
119	    public Collection<Visit> findAllVisits() throws DataAccessException {
120	        return visitRepository.findAll();
121	    }
122	
123	    @Override
124	    @Transactional
125	    public void deleteVisit(Visit visit) throws DataAccessException {
126	        visitRepository.delete(visit);
127	    }
128	
129	    @Override
130	    @Transactional(readOnly = true)
131	    public Vet findVetById(int id) throws DataAccessException {
132	        return findEntityById(() -> vetRepository.findById(id));
133	    }
134	
135	    @Override
136	    @Transactional(readOnly = true)
137	    public Collection<Vet> findAllVets() throws DataAccessException {
138	        return vetRepository.findAll();
139	    }
140	
141	    @Override
142	    @Transactional
143	    public void saveVet(Vet vet) throws DataAccessException {
144	        vetRepository.save(vet);
145	    }
146	
147	    @Override
148	    @Transactional
149	    public void deleteVet(Vet vet) throws DataAccessException {
150	        vetRepository.delete(vet);
151	    }
152	
153	    @Override
154	    @Transactional(readOnly = true)
155	    public Collection<Owner> findAllOwners() throws DataAccessException {
156	        Collection<Owner> owners = ownerRepository.findAll();
157	        populateHouseholdSizes(owners);
158	        return owners;
159	    }
160	
161	    @Override
162	    @Transactional(readOnly = true)
163	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
164	        Page<Owner> owners = (lastName != null)
165	            ? ownerRepository.findByLastName(lastName, pageable)
166	            : ownerRepository.findAll(pageable);
167	        populateHouseholdSizes(owners.getContent());
168	        return owners;
169	    }
170	
171	    @Override
172	    @Transactional
173	    public void deleteOwner(Owner owner) throws DataAccessException {
174	        owner.setDeleted(true);
175	        ownerRepository.save(owner);
176	    }
177	
178	    @Override
179	    @Transactional(readOnly = true)
180	    public PetType findPetTypeById(int petTypeId) {
181	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
182	    }
183	
184	    @Override
185	    @Transactional(readOnly = true)
186	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
187	        return petTypeRepository.findAll();
188	    }
189	
190	    @Override
191	    @Transactional
192	    public void savePetType(PetType petType) throws DataAccessException {
193	        petTypeRepository.save(petType);
194	    }
195	
196	    @Override
197	    @Transactional
198	    public void deletePetType(PetType petType) throws DataAccessException {
199	        petTypeRepository.delete(petType);
200	    }
201	
202	    @Override
203	    @Transactional(readOnly = true)
204	    public Specialty findSpecialtyById(int specialtyId) {
205	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
206	    }
207	
208	    @Override
209	    @Transactional(readOnly = true)
210	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
211	        return specialtyRepository.findAll();
212	    }
213	
214	    @Override
215	    @Transactional
216	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
217	        specialtyRepository.save(specialty);
218	    }
219	
220	    @Override
221	    @Transactional
222	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
223	        specialtyRepository.delete(specialty);
224	    }
225	
226	    @Override
227	    @Transactional(readOnly = true)
228	    public Collection<PetType> findPetTypes() throws DataAccessException {
229	        return petRepository.findPetTypes();
230	    }
231	
232	    @Override
233	    @Transactional(readOnly = true)
234	    public Owner findOwnerById(int id) throws DataAccessException {
235	        Owner owner = findEntityById(() -> ownerRepository.findById(id));
236	        populateHouseholdSize(owner);
237	        return owner;
238	    }
239	
240	    @Override
241	    @Transactional(readOnly = true)
242	    public Pet findPetById(int id) throws DataAccessException {
243	        return findEntityById(() -> petRepository.findById(id));
244	    }
245	
246	    @Override
247	    @Transactional
248	    public void savePet(Pet pet) throws DataAccessException {
249	        pet.setType(findPetTypeById(pet.getType().getId()));
250	        petRepository.save(pet);
251	    }
252	
253	    @Override
254	    @Transactional
255	    public void saveVisit(Visit visit) throws DataAccessException {
256	        visitRepository.save(visit);
257	
258	    }
259	
260	    @Override
261	    @Transactional(readOnly = true)
262	    public Collection<Vet> findVets() throws DataAccessException {
263	        return vetRepository.findAll();
264	    }
265	
266	    /**
267	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
268	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
269	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
270	     * a known region (see {@link Region}), the postcode must fall within that region's range
271	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
272	     * postcode.
273	     *
274	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
275	     */
276	    private void assertPostcodeValid(Owner owner) {
277	        String postcode = owner.getPostcode();
278	        if (postcode == null) {
279	            return;
280	        }
281	        String region = Region.forCity(owner.getCity());
282	        int[] range = region == null ? null : Region.postcodeRange(region);
283	        if (range == null) {
284	            return;
285	        }
286	        int value = Integer.parseInt(postcode);
287	        if (value < range[0] || value > range[1]) {
288	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
289	        }
290	    }
291	
292	    /**
293	     * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
294	     * server date. The registration date is optional: a {@code null} date is left untouched (it is
295	     * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
296	     *
297	     * @throws FutureRegistrationDateException if the supplied registration date is after today
298	     */
299	    private void assertRegistrationDateNotFuture(Owner owner) {
300	        LocalDate registrationDate = owner.getRegistrationDate();
301	        if (registrationDate == null) {
302	            return;
303	        }
304	        LocalDate today = LocalDate.now();
305	        if (registrationDate.isAfter(today)) {
306	            throw new FutureRegistrationDateException(registrationDate, today);
307	        }
308	    }
309	
310	    /** Email domains rejected as disposable/throwaway addresses. */
311	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
312	        "mailinator.com", "tempmail.com", "guerrillamail.com");
313	
314	    /**
315	     * The base (second-level) labels of the {@link #DISPOSABLE_EMAIL_DOMAINS}, e.g. {@code
316	     * "mailinator"} for {@code "mailinator.com"}. A domain is treated as disposable-adjacent when any
317	     * of its dot-separated labels equals one of these, so subdomains of a disposable domain and the
318	     * same base name under a different TLD are both caught (see {@link
319	     * #isEmailDomainDisposableAdjacent(String)}).
320	     */
321	    private static final Set<String> DISPOSABLE_EMAIL_BASE_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
322	        .map(domain -> domain.substring(0, domain.indexOf('.')))
323	        .collect(java.util.stream.Collectors.toUnmodifiableSet());
324	
325	    /**
326	     * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
327	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
328	     * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
329	     * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
330	     *
331	     * @throws DisposableEmailDomainException if the email domain is blocklisted
332	     */
333	    private void assertEmailDomainAllowed(Owner owner) {
334	        String email = owner.getEmail();
335	        if (email == null) {
336	            return;
337	        }
338	        int at = email.lastIndexOf('@');
339	        if (at < 0) {
340	            return;
341	        }
342	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
343	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
344	            throw new DisposableEmailDomainException(domain);
