391	    /**
392	     * Builds the immutable structured {@code OWNER_CREATED} audit event as a compact JSON object
393	     * {@code {seq, ownerId, memberId, membershipLevel, event}}. The {@code seq} is a
394	     * process-wide, monotonically increasing integer stamped once per created owner.
395	     *
396	     * <p>The identifier field carries the owner's <em>current primary identifier</em>, sourced
397	     * through {@link #primaryIdentifier(Owner)} — the unified {@code memberId}.
398	     */
399	    private String ownerCreatedEvent(Owner owner) {
400	        Map<String, Object> event = new LinkedHashMap<>();
401	        event.put("seq", OWNER_CREATED_SEQ.incrementAndGet());
402	        event.put("ownerId", owner.getId());
403	        event.put("memberId", primaryIdentifier(owner));
404	        event.put("membershipLevel", owner.getMembershipLevel());
405	        event.put("event", "OWNER_CREATED");
