409	    /**
410	     * The owner's current primary identifier — the unified {@code memberId}. This is the single
411	     * place to switch so every consumer (notably the structured audit event) follows.
412	     */
413	    private String primaryIdentifier(Owner owner) {
414	        return owner.getMemberId();
415	    }
416	
417	    /**
418	     * Build a {@code memberId} formatted {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region
419	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}); FY is
420	     * the two-digit fiscal year of the owner's (business-day-adjusted) {@code registrationDate} (see
421	     * {@link Owner#fiscalYearOf(LocalDate)}); HASH8 is the first 8 upper-case hex characters of the
422	     * SHA-256 digest over the concatenation of the owner's normalized telephone and {@code lastName};
423	     * and CHK is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.
424	     * The telephone is already normalized and the registration date defaulted by
425	     * {@link #saveOwner(Owner)} before this runs. The layout is read back by
426	     * {@link Region#regionOfMemberId(String)}; keep the two in sync.
427	     */
428	    private String generateMemberId(Owner owner) {
429	        String region = Region.regionForPostcode(owner.getPostcode());
430	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
431	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
432	        String hash8 = Sha256Hex.upperHex(telephone + lastName, 8);
433	        LocalDate registrationDate = owner.getRegistrationDate();
434	        String fy = registrationDate == null
435	            ? "00" : String.format("%02d", Owner.fiscalYearOf(registrationDate) % 100);
436	        String base = region + fy + hash8;
437	        String memberId = base + luhnCheckDigit(base);
438	        return deduplicateMemberId(owner, memberId);
439	    }
440	
441	    /**
442	     * A single Luhn check digit (0-9) computed over the decimal digits contained in {@code value}
443	     * (non-digit characters, such as the region letters and hex letters, are ignored).
444	     */
445	    private static int luhnCheckDigit(String value) {
446	        int sum = 0;
447	        boolean dbl = true;
448	        for (int i = value.length() - 1; i >= 0; i--) {
449	            char c = value.charAt(i);
450	            if (c < '0' || c > '9') {
451	                continue;
452	            }
453	            int d = c - '0';
454	            if (dbl) {
455	                d *= 2;
456	                if (d > 9) {
457	                    d -= 9;
458	                }
459	            }
460	            sum += d;
461	            dbl = !dbl;
462	        }
463	        return (10 - (sum % 10)) % 10;
464	    }
465	
466	    /**
467	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
468	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
469	     * existing owners' {@code memberId}s. The {@code owner} being saved is excluded from the
470	     * comparison so re-saving it does not treat its own id as a collision.
471	     */
472	    private String deduplicateMemberId(Owner owner, String base) {
473	        Set<String> taken = new HashSet<>();
474	        for (Owner existing : ownerRepository.findAll()) {
475	            if (!existing.getId().equals(owner.getId()) && existing.getMemberId() != null) {
476	                taken.add(existing.getMemberId());
477	            }
478	        }
479	        if (!taken.contains(base)) {
480	            return base;
481	        }
482	        int n = 2;
483	        while (taken.contains(base + "-" + n)) {
484	            n++;
485	        }
486	        return base + "-" + n;
487	    }
