583	    /** Fixed public holidays that the business-day roll skips. */
584	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
585	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
586	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
