589	    /**
590	     * Rolls {@code date} forward to the next business day. A business day is Monday to Friday that is
591	     * not a listed public holiday; Saturdays, Sundays and public holidays are skipped by advancing
592	     * one day at a time until a business day is reached. Business days are returned unchanged.
593	     */
594	    private static LocalDate rollToBusinessDay(LocalDate date) {
595	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
596	            date = date.plusDays(1);
597	        }
598	        return date;
599	    }
