682	    /**
683	     * Normalizes whichever address fields {@code owner} supplied and derives the effective flat
684	     * {@code address} from them. The structured form is preferred: when a non-blank
685	     * {@code addressLine1} is present, {@code address} is set to the normalized {@code addressLine1},
686	     * with a single space and the normalized {@code addressLine2} appended when {@code addressLine2}
687	     * is present. Otherwise the flat {@code address} is normalized in place (backward-compatible). The
688	     * structured fields are also stored in their normalized form. Because everything downstream reads
689	     * {@link Owner#getAddress()}, the household hash, postcode validation and locality all see the
690	     * structured value when present and fall back to the flat address otherwise.
691	     */
692	    private static void applyAddress(Owner owner) {
693	        String line1 = normalizeAddress(owner.getAddressLine1());
694	        String line2 = normalizeAddress(owner.getAddressLine2());
695	        owner.setAddressLine1(line1);
696	        owner.setAddressLine2(line2);
697	        if (line1 != null && !line1.isEmpty()) {
698	            String composed = (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
699	            owner.setAddress(composed);
700	        } else if (owner.getAddress() != null) {
701	            owner.setAddress(normalizeAddress(owner.getAddress()));
702	        }
703	    }
704	
705	    /** Common street-type abbreviations expanded during address normalization. */
706	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
707	        "ST", "STREET",
708	        "RD", "ROAD",
709	        "AVE", "AVENUE");
710	
711	    /**
712	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
713	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
714	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
715	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
716	     * form.
717	     */
718	    private static String normalizeAddress(String address) {
719	        if (address == null) {
720	            return null;
721	        }
722	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
723	        if (collapsed.isEmpty()) {
724	            return "";
725	        }
726	        String[] tokens = collapsed.split(" ");
727	        StringBuilder sb = new StringBuilder(collapsed.length());
728	        for (int i = 0; i < tokens.length; i++) {
729	            if (i > 0) {
730	                sb.append(' ');
731	            }
732	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
733	        }
734	        return sb.toString();
735	    }
736	
737	    private static String normalizeTelephone(String telephone) {
738	        return telephone == null ? null : E164Telephone.toE164(telephone);
739	    }
