741	    /**
742	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
743	     * that of another non-deleted owner. The key is the SHA-256 hex over the normalized telephone,
744	     * lower-cased email and {@code soundex(lastName)}, so it consolidates the former separate
745	     * telephone, email and household duplicate rules into a single check — only an exact full-key
746	     * match is a hard duplicate. Owners flagged {@link Owner#isDeleted() deleted} are ignored.
747	     *
748	     * @throws DuplicateIdentityException if another owner already has the same identity key
749	     */
750	    private void assertIdentityUnique(Owner owner) {
751	        String identityKey = owner.getIdentityKey();
752	        for (Owner existing : ownerRepository.findAll()) {
753	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
754	                    && identityKey.equals(existing.getIdentityKey())) {
755	                throw new DuplicateIdentityException(identityKey);
756	            }
757	        }
758	    }
759	
760	    /**
761	     * Flags {@code owner} as a soft match ({@link Owner#isPossibleDuplicate()} /
762	     * {@link Owner#getPossibleDuplicateOf()}) when its {@link Owner#getIdentityKey() identity key}
763	     * differs from every existing owner's (so it is not a hard duplicate) yet it shares an existing,
764	     * non-deleted owner's {@code soundex(lastName)} and {@code postcode}. This is what now admits two
765	     * owners with the same {@code lastName} and {@code postcode} but different telephones: they are
766	     * created as a soft match rather than rejected. The first matching owner (by store iteration
767	     * order) is recorded. Any prior flag is cleared first, and no match is possible when the owner
768	     * has no postcode or a last name that yields an empty soundex.
769	     */
770	    private void applySoftMatch(Owner owner) {
771	        owner.setPossibleDuplicate(false);
772	        owner.setPossibleDuplicateOf(null);
773	        String soundex = Soundex.encode(owner.getLastName());
774	        String postcode = owner.getPostcode();
775	        if (soundex.isEmpty() || postcode == null || postcode.isBlank()) {
776	            return;
777	        }
778	        String identityKey = owner.getIdentityKey();
779	        for (Owner existing : ownerRepository.findAll()) {
780	            if (existing.getId().equals(owner.getId()) || existing.isDeleted()) {
781	                continue;
782	            }
783	            if (!identityKey.equals(existing.getIdentityKey())
784	                    && soundex.equals(Soundex.encode(existing.getLastName()))
785	                    && postcode.equals(existing.getPostcode())) {
786	                owner.setPossibleDuplicate(true);
787	                owner.setPossibleDuplicateOf(existing.getId());
788	                return;
789	            }
790	        }
791	    }
