793	    /**
794	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
795	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
796	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
797	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
798	     * household is keyed on both.
799	     */
800	    private void assignHouseholdId(Owner owner) {
801	        String lastName = normalizeHouseholdValue(owner.getLastName());
802	        String postcode = owner.getPostcode();
803	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
804	            owner.setHouseholdId(null);
805	            return;
806	        }
807	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
808	    }
