810	    /**
811	     * Captures the membership-level ceiling for a newly created {@code owner}: its
812	     * {@link Owner#getMembershipLevel() membership level} may not exceed one above the highest level
813	     * among the household members (owners sharing its {@code householdId}) that already exist. When
814	     * the owner belongs to no household, or no existing member shares it, no cap applies and the
815	     * level is left uncapped. Each existing member's household size is stamped via
816	     * {@link #populateHouseholdSizes(Collection)} first so its level reflects the household-size
817	     * membership points.
818	     *
819	     * @see Owner#getMembershipLevelCap()
820	     */
821	    private void applyMembershipLevelCap(Owner owner) {
822	        owner.setMembershipLevelCap(null);
823	        String householdId = owner.getHouseholdId();
824	        if (householdId == null || householdId.isBlank()) {
825	            return;
826	        }
827	        List<Owner> members = new ArrayList<>();
828	        for (Owner existing : ownerRepository.findAll()) {
829	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
830	                    && householdId.equals(existing.getHouseholdId())) {
831	                members.add(existing);
832	            }
833	        }
834	        if (members.isEmpty()) {
835	            return;
836	        }
837	        populateHouseholdSizes(members);
838	        int maxLevel = 0;
839	        for (Owner member : members) {
840	            maxLevel = Math.max(maxLevel, member.getMembershipLevel());
841	        }
842	        owner.setMembershipLevelCap(maxLevel + 1);
843	    }
