845	    /**
846	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
847	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
848	     * reaching into the data store. A {@code null} owner or one without a household id is left at
849	     * size 0.
850	     */
851	    private void populateHouseholdSize(Owner owner) {
852	        if (owner == null) {
853	            return;
854	        }
855	        String householdId = owner.getHouseholdId();
856	        if (householdId == null || householdId.isBlank()) {
857	            owner.setHouseholdSize(0);
858	            return;
859	        }
860	        int count = 0;
861	        for (Owner existing : ownerRepository.findAll()) {
862	            if (householdId.equals(existing.getHouseholdId())) {
863	                count++;
864	            }
865	        }
866	        owner.setHouseholdSize(count);
867	    }
