869	    /**
870	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
871	     * store, so a list/page of owners is counted without a per-owner query.
872	     *
873	     * @see #populateHouseholdSize(Owner)
874	     */
875	    private void populateHouseholdSizes(Collection<Owner> owners) {
876	        if (owners.isEmpty()) {
877	            return;
878	        }
879	        Map<String, Integer> sizes = new HashMap<>();
880	        for (Owner existing : ownerRepository.findAll()) {
881	            String householdId = existing.getHouseholdId();
882	            if (householdId != null && !householdId.isBlank()) {
883	                sizes.merge(householdId, 1, Integer::sum);
884	            }
885	        }
886	        for (Owner owner : owners) {
887	            String householdId = owner.getHouseholdId();
888	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
889	        }
890	    }
