6	import org.mapstruct.Mapping;
7	import org.mapstruct.MappingTarget;
8	import org.springframework.data.domain.Page;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.model.Region;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    OwnerDto toOwnerDto(Owner owner);
25	
26	    /**
27	     * Fills the presentation-only {@code displayName} as {@code "LastName, FirstName"}
28	     * from the stored names, once MapStruct has mapped the remaining fields.
29	     */
30	    @AfterMapping
31	    default void addDisplayName(Owner owner, @MappingTarget OwnerDto ownerDto) {
32	        ownerDto.setDisplayName(owner.getLastName() + ", " + owner.getFirstName());
33	    }
34	
35	    /**
36	     * Fills the presentation-only {@code salutation} from the owner's domain-computed
37	     * {@link Owner#getSalutation()} — the title and lastName separated by a space, or just the
38	     * lastName when the owner has no title.
39	     */
40	    @AfterMapping
41	    default void addSalutation(Owner owner, @MappingTarget OwnerDto ownerDto) {
42	        ownerDto.setSalutation(owner.getSalutation());
43	    }
44	
45	    /**
46	     * Fills the presentation-only {@code initials} as the upper-cased first letters of
47	     * firstName and lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
48	     */
49	    @AfterMapping
50	    default void addInitials(Owner owner, @MappingTarget OwnerDto ownerDto) {
51	        ownerDto.setInitials(
52	            Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
53	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".");
54	    }
55	
56	    /**
57	     * Fills the presentation-only {@code fiscalYear} from the owner's domain-computed
58	     * {@link Owner#getFiscalYear()} — {@code 'FY<YY>'} derived from the business-day-adjusted
59	     * registrationDate — leaving it null when no registration date is available.
60	     */
61	    @AfterMapping
62	    default void addFiscalYear(Owner owner, @MappingTarget OwnerDto ownerDto) {
63	        ownerDto.setFiscalYear(owner.getFiscalYear());
64	    }
65	
66	    /**
67	     * Fills the {@code membershipPoints} and {@code membershipLevel} from the owner's
68	     * domain-computed {@link Owner#getMembershipPoints()} and {@link Owner#getMembershipLevel()}.
69	     */
70	    @AfterMapping
71	    default void addMembershipLevel(Owner owner, @MappingTarget OwnerDto ownerDto) {
72	        ownerDto.setMembershipPoints(owner.getMembershipPoints());
73	        ownerDto.setMembershipLevel(owner.getMembershipLevel());
74	    }
75	
76	    /**
77	     * Fills the {@code contactPreference} as {@code EMAIL} when the owner has an email
78	     * address, otherwise {@code PHONE}.
79	     */
80	    @AfterMapping
81	    default void addContactPreference(Owner owner, @MappingTarget OwnerDto ownerDto) {
82	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
83	        ownerDto.setContactPreference(
84	            hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE);
85	    }
86	
87	    /**
88	     * Fills the presentation-only {@code locality} as the {@code <REGION>} component of the owner's
89	     * {@code memberId} (see {@link Region#regionOfMemberId(String)}) — the region-and-hash
90	     * identity is the single source of truth — or {@code 'UNKNOWN'} when no memberId is assigned.
91	     */
92	    @AfterMapping
93	    default void addLocality(Owner owner, @MappingTarget OwnerDto ownerDto) {
94	        ownerDto.setLocality(Region.regionOfMemberId(owner.getMemberId()));
95	    }
96	
97	    /**
98	     * Fills the presentation-only {@code timezone} as the IANA timezone name derived from the
99	     * owner's locality/region (the {@code <REGION>} component of its {@code memberId}) via the
100	     * fixed region-to-timezone table (see {@link Region#timezoneForRegion(String)}), or {@code null}
101	     * when the region has no mapped timezone.
102	     */
103	    @AfterMapping
104	    default void addTimezone(Owner owner, @MappingTarget OwnerDto ownerDto) {
105	        ownerDto.setTimezone(Region.timezoneForRegion(Region.regionOfMemberId(owner.getMemberId())));
106	    }
107	
108	    /**
109	     * Fills the presentation-only {@code ownerSegment} from the owner's domain-computed
110	     * {@link Owner#getOwnerSegment()} — {@code '<TIER>_<AREA>'} where TIER reflects the
111	     * membershipLevel and AREA reflects whether the locality is a known region.
112	     */
113	    @AfterMapping
114	    default void addOwnerSegment(Owner owner, @MappingTarget OwnerDto ownerDto) {
115	        ownerDto.setOwnerSegment(OwnerDto.OwnerSegmentEnum.fromValue(owner.getOwnerSegment()));
116	    }
117	
118	    /**
119	     * Fills the {@code ageBand} from the owner's domain-computed {@link Owner#getAgeBand()}
120	     * (derived from birthDate measured against registrationDate), leaving it null when no
121	     * birth date is available.
122	     */
123	    @AfterMapping
124	    default void addAgeBand(Owner owner, @MappingTarget OwnerDto ownerDto) {
125	        String ageBand = owner.getAgeBand();
126	        if (ageBand != null) {
127	            ownerDto.setAgeBand(OwnerDto.AgeBandEnum.fromValue(ageBand));
128	        }
129	    }
130	
131	    /**
132	     * Fills the presentation-only {@code selfLink} as {@code '/api/owners/'} followed by the
133	     * owner's id, leaving it null when the owner has no id assigned yet.
134	     */
135	    @AfterMapping
136	    default void addSelfLink(Owner owner, @MappingTarget OwnerDto ownerDto) {
137	        if (owner.getId() != null) {
138	            ownerDto.setSelfLink("/api/owners/" + owner.getId());
139	        }
140	    }
141	
142	    Owner toOwner(OwnerDto ownerDto);
143	
144	    @Mapping(target = "id", ignore = true)
145	    @Mapping(target = "pets", ignore = true)
146	    Owner toOwner(OwnerFieldsDto ownerDto);
147	
148	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
149	
150	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
151	
152	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
153	        OwnerPageDto ownerPageDto = new OwnerPageDto();
154	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
155	        ownerPageDto.setPage(ownerPage.getNumber());
156	        ownerPageDto.setSize(ownerPage.getSize());
