18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.servlet.http.HttpServletRequest;
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    private final IdempotencyStore idempotencyStore;
66	
67	    private final HttpServletRequest request;
68	
69	    /** Header carrying the client-supplied idempotency token on a create request. */
70	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper,
76	                                 IdempotencyStore idempotencyStore,
77	                                 HttpServletRequest request) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	        this.idempotencyStore = idempotencyStore;
83	        this.request = request;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        List<OwnerDto> ownerDtos = ownerMapper.toOwnerDtoCollection(owners);
99	        ownerDtos.forEach(this::withDerivedWarnings);
100	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(withDerivedWarnings(ownerMapper.toOwnerDto(owner)), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        String idempotencyKey = idempotencyKey();
117	        if (idempotencyKey != null) {
118	            Integer existingId = this.idempotencyStore.find(idempotencyKey);
119	            if (existingId != null) {
120	                Owner existing = this.clinicService.findOwnerById(existingId);
121	                if (existing != null) {
122	                    return new ResponseEntity<>(withDerivedWarnings(ownerMapper.toOwnerDto(existing)),
123	                        HttpStatus.OK);
124	                }
125	            }
126	        }
127	        HttpHeaders headers = new HttpHeaders();
128	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
129	        this.clinicService.saveOwner(owner);
130	        if (idempotencyKey != null) {
131	            this.idempotencyStore.remember(idempotencyKey, owner.getId());
132	        }
133	        OwnerDto ownerDto = withDerivedWarnings(ownerMapper.toOwnerDto(owner));
134	        headers.setLocation(UriComponentsBuilder.newInstance()
135	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
136	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
137	    }
138	
139	    /**
140	     * The trimmed {@code Idempotency-Key} header of the current request, or {@code null} when it is
141	     * absent or blank (an absent key means the create is treated non-idempotently).
142	     */
143	    private String idempotencyKey() {
144	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
145	        if (key == null) {
146	            return null;
147	        }
148	        key = key.trim();
149	        return key.isEmpty() ? null : key;
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
155	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
156	        if (currentOwner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        currentOwner.setAddress(ownerFieldsDto.getAddress());
160	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
161	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
162	        currentOwner.setCity(ownerFieldsDto.getCity());
163	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
164	        currentOwner.setLastName(ownerFieldsDto.getLastName());
165	        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
166	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
167	        currentOwner.setEmail(ownerFieldsDto.getEmail());
168	        this.clinicService.saveOwner(currentOwner);
169	        return new ResponseEntity<>(withDerivedWarnings(ownerMapper.toOwnerDto(currentOwner)),
170	            HttpStatus.NO_CONTENT);
171	    }
172	
173	    /**
174	     * Sets the derived warning flags on {@code ownerDto}. {@code bulkSignupWarning} reflects the
175	     * current day's signup volume (the same for every owner in a response); {@code capacityWarning}
176	     * is city-specific, true when the owner's city is approaching the per-city capacity limit.
177	     * {@code riskFlag} aggregates the individual risk signals into a single indicator.
178	     */
179	    private OwnerDto withDerivedWarnings(OwnerDto ownerDto) {
180	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupWarningActive());
181	        ownerDto.setCapacityWarning(this.clinicService.isCityCapacityWarningActive(ownerDto.getCity()));
182	        ownerDto.setRiskFlag(this.clinicService.isOwnerRiskFlagged(
183	            Boolean.TRUE.equals(ownerDto.getPossibleDuplicate()), ownerDto.getEmail(), ownerDto.getCity()));
184	        return ownerDto;
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Transactional
189	    @Override
190	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        this.clinicService.deleteOwner(owner);
196	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        HttpHeaders headers = new HttpHeaders();
207	        Pet pet = petMapper.toPet(petFieldsDto);
208	        owner.setId(ownerId);
209	        pet.setOwner(owner);
210	        pet.getType().setName(null);
211	        this.clinicService.savePet(pet);
212	        PetDto petDto = petMapper.toPetDto(pet);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
214	            .buildAndExpand(pet.getId()).toUri());
215	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
221	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
222	        if (currentOwner != null) {
223	            Pet currentPet = this.clinicService.findPetById(petId);
224	            if (currentPet != null) {
225	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
226	                currentPet.setName(petFieldsDto.getName());
227	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
228	                this.clinicService.savePet(currentPet);
229	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
238	        HttpHeaders headers = new HttpHeaders();
239	        Visit visit = visitMapper.toVisit(visitFieldsDto);
240	        Pet pet = new Pet();
241	        pet.setId(petId);
242	        visit.setPet(pet);
243	        this.clinicService.saveVisit(visit);
